/* =========================================================
   Seller Central + shared ops shell
   ========================================================= */
function opShell(role,menu,v,dev){const r=S.r[role];const isS=role==='seller';const n=unread(role);const sh=isS?SL(S.seller.shop):null;
  const sb=dev==='mobile'?`<div class="statusbar ops"><span>9:41</span><span class="xs">5G ▮▮▮ 🔋</span></div>`:'';
  return `${sb}<div class="op"><header class="op-top ${isS?'':'adm'}">
   <button class="logo" onclick="go('${role}','dashboard')">ecomdemo<b>.</b><small>${isS?'seller central':'admin'}</small></button>
   ${isS?`<button class="sw" onclick="storeSwitch()">${mono(sh,'sm')}<span class="lbl">${esc(sh.name)}</span>${ic('down','sm')}</button>`:`<span class="sw"><span class="lbl">Marketplace Ops · US</span></span>`}
   <label class="osrch">${ic('search','sm')}<input placeholder="${isS?'Search orders, SKUs, listings':'Search sellers, orders, listings'}" onkeydown="if(event.key==='Enter'){go('${role}','${isS?'listings':'moderation'}',{q:this.value})}"></label>
   <span class="grow"></span>
   <button class="iconbtn hide-m" onclick="toast('${isS?'Seller Support: chat or call 7 AM–9 PM PT, English & Tiếng Việt':'Runbooks and policies are linked from each queue'}','help')" aria-label="Help">${ic('help')}</button>
   <button class="iconbtn" onclick="UI.notif=UI.notif==='${role}'?null:'${role}';render('${role}')" aria-label="Notifications">${ic('bell')}${n?`<span class="cnt">${n}</span>`:''}</button>
   <span class="avatar" style="background:#33465F;color:#fff">${isS?'NH':'QA'}</span>
   ${UI.notif===role?`<div class="notif"><div class="row between" style="padding:12px 14px;border-bottom:1px solid var(--line)"><b>Notifications</b><button class="lnk xs" onclick="S.notifs.forEach(n=>{if(n.role==='${role}')n.read=true});render('${role}')">Mark all as read</button></div>${S.notifs.filter(x=>x.role===role).slice(0,12).map(x=>`<button class="it ${x.read?'':'un'}" onclick="openNotif('${role}',${S.notifs.indexOf(x)})"><span class="dot" style="background:${x.read?'transparent':'var(--op)'};margin-top:6px"></span><span class="grow"><span>${x.text}</span><br><span class="xs faint">${ago(x.t)}</span></span></button>`).join('')||'<div class="empty">No notifications</div>'}</div>`:''}
  </header>
  <div class="op-body"><nav class="side">${menu.map(m=>m.g?`<div class="grp">${m.g}</div>`:`<button class="${r.n===m.n||(m.alt||[]).includes(r.n)?'on':''}" onclick="go('${role}','${m.n}',${J(m.p||{})})">${ic(m.i)}<span>${m.l}</span>${m.c?`<span class="cnt">${m.c}</span>`:''}</button>`).join('')}</nav>
   <div class="op-main"><div class="vp"><div class="op-ph">${r.h.length?`<button class="iconbtn" onclick="back('${role}')" aria-label="Back">${ic('back')}</button>`:''}<h1>${v.title}${v.sub?`<span class="sub">${v.sub}</span>`:''}</h1>${v.actions||''}</div>${v.body}</div></div></div></div>${overlay(role)}`}
function openNotif(role,i){const n=S.notifs[i];n.read=true;UI.notif=null;if(n.link)go(role,n.link[0],n.link[1]);else render(role)}
function kpi(k,v,d,cls='',icn){return `<div class="kpi"><div class="k">${icn?ic(icn,'sm'):''}${k}</div><div class="v">${v}</div>${d?`<div class="d ${cls}">${d}</div>`:''}</div>`}
function tabs(role,screen,list,cur,extra={}){return `<div class="otabs">${list.map(([k,l,n])=>`<button class="${cur===k?'on':''}" onclick="go('${role}','${screen}',${J({...extra,tab:k})},true)">${l}${n!=null?`<span class="n">${n}</span>`:''}</button>`).join('')}</div>`}
function miniP(p,sub){return `<div class="mini">${pimg(p,120)}<div style="min-width:0"><div class="sm ell" style="max-width:300px">${esc(p.en)}</div>${sub?`<div class="xs faint">${sub}</div>`:''}</div></div>`}
function barChart(vals,labels,{w=640,h=210,color='var(--op)',fmt=moneyK}={}){const max=Math.max(...vals)*1.12||1,n=vals.length,bw=(w-44)/n;
  return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Bar chart">${[0,.5,1].map(f=>`<line x1="44" x2="${w}" y1="${h-22-(h-36)*f}" y2="${h-22-(h-36)*f}" stroke="var(--line-2)"/><text x="38" y="${h-18-(h-36)*f}" font-size="10" text-anchor="end" fill="var(--text-3)">${fmt(max*f)}</text>`).join('')}
  ${vals.map((v,i)=>{const bh=(h-36)*v/max;return `<rect x="${44+i*bw+bw*.18}" y="${h-22-bh}" width="${bw*.64}" height="${Math.max(bh,1)}" rx="2" fill="${color}" opacity="${i===n-1?1:.72}"><title>${labels[i]}: ${fmt(v)}</title></rect>${i%Math.ceil(n/10)===0||i===n-1?`<text x="${44+i*bw+bw/2}" y="${h-6}" font-size="10" text-anchor="middle" fill="var(--text-3)">${labels[i]}</text>`:''}`}).join('')}</svg></div>`}
const dayLbl=i=>new Date(Date.now()-i*DAY).toLocaleDateString('en-US',{month:'short',day:'numeric'});

/* ---------- Seller shell ---------- */
const SS={};
const myShop=()=>S.seller.shop;
const sOrders=()=>S.orders.filter(o=>o.seller===myShop()).sort((a,b)=>b.created-a.created);
const sProducts=()=>S.products.filter(p=>p.seller===myShop());
VIEWS.seller=dev=>{const r=S.r.seller;const v=(SS[r.n]||SS.dashboard)(r.p||{});const os=sOrders();
  const un=os.filter(o=>o.status==='unshipped').length,rt=os.filter(o=>o.status==='return_requested'&&o.returnReq.status==='requested').length,q=S.questions.filter(x=>!x.a&&P(x.pid)&&P(x.pid).seller===myShop()).length;
  const menu=[{g:'Overview'},{n:'dashboard',l:'Home',i:'home'},{g:'Catalog'},{n:'listings',l:'Manage listings',i:'list'},{n:'add',l:'Add a product',i:'plus'},{n:'bulk',l:'Bulk upload',i:'upload'},
   {g:'Orders'},{n:'orders',l:'Manage orders',i:'box',c:un,alt:['order'],p:{tab:'unshipped'}},{n:'returns',l:'Returns & claims',i:'return',c:rt},
   {g:'Business'},{n:'payments',l:'Payments',i:'wallet'},{n:'feedback',l:'Customer questions',i:'chat',c:q},{n:'settings',l:'Store settings',i:'settings'},{n:'onboard',l:'Register a new business',i:'id'}];
  return opShell('seller',menu,v,dev)};
function storeSwitch(){const all=[...SELLERS.filter(s=>s.id==='s1'),...(S.newSellers||[])];
  openOv('seller',`<div class="modal" style="width:min(420px,100%)">${mHead('seller','Switch store')}<div class="modal-b">${all.map(s=>`<button class="opt ${s.id===myShop()?'on':''}" onclick="S.seller.shop='${s.id}';UI.ov.seller=null;go('seller','dashboard')">${mono(s,'sm')}<span class="sm grow"><b>${esc(s.name)}</b><br><span class="muted">${esc(s.legal)} · ${esc(s.city)}</span></span>${s.id===myShop()?ic('check','sm'):''}</button>`).join('')}
  <button class="btn block mt12" onclick="UI.ov.seller=null;go('seller','onboard')">${ic('plus','sm')} Register another business</button></div></div>`)}

/* ---------- Dashboard ---------- */
SS.dashboard=()=>{const os=sOrders();const sh=SL(myShop());const today=os.filter(o=>Date.now()-o.created<DAY&&o.status!=='cancelled');
  const seedRev=myShop()==='s1'?Array.from({length:30},(_,i)=>{const r=rng('rv'+i)();return Math.round(380+Math.sin(i/3.5)*120+r*260+(i>22?140:0))}):Array(30).fill(0);
  const vals=seedRev.map((v,i)=>i===29?v+today.reduce((a,o)=>a+subOf(o),0):v);
  const un=os.filter(o=>o.status==='unshipped');const low=sProducts().filter(p=>p.status==='active'&&p.stock<=5);const rev=sProducts().filter(p=>p.status==='review');
  const rets=os.filter(o=>o.status==='return_requested'&&o.returnReq.status==='requested');const qs=S.questions.filter(x=>!x.a&&P(x.pid)&&P(x.pid).seller===myShop());
  const top=sProducts().filter(p=>p.status==='active').sort((a,b)=>b.bought-a.bought).slice(0,5);
  const todo=[['Orders to ship',un.length,"go('seller','orders',{tab:'unshipped'})",un.length?'Ship by '+dayShort(addBiz(Date.now(),S.seller.settings.handling)):''],['Return requests',rets.length,"go('seller','returns')",'Respond within 48 hours'],['Unanswered customer questions',qs.length,"go('seller','feedback')",''],['Listings under review',rev.length,"go('seller','listings',{tab:'review'})",''],['Low inventory (5 or fewer)',low.length,"go('seller','listings',{tab:'active'})",low.map(p=>p.sku).join(', ')]];
  return{title:`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${sh.id==='s1'?'Hung':'there'}`,sub:`${esc(sh.name)} · ${esc(sh.city)}`,
  actions:`<button class="btn" onclick="go('buyer','store',{id:'${sh.id}'})">${ic('eye','sm')} View storefront</button><button class="btn pri" onclick="UI.tmp.ep=null;go('seller','add')">${ic('plus','sm')} Add a product</button>`,
  body:`${!sProducts().length?`<div class="alert info mb16">${ic('info','sm')}<div class="grow"><b>Your store is approved.</b> Add your first product, or upload your catalog as a CSV file.</div><button class="btn pri sm" onclick="UI.tmp.ep=null;go('seller','add')">Add a product</button><button class="btn sm" onclick="go('seller','bulk')">Bulk upload</button></div>`:''}
  <div class="grid c4">${kpi("Today's sales",money(vals[29]),'▲ 12% vs. same day last week','up','chart')}${kpi('Orders to ship',un.length,un.length?'Oldest: '+ago(un[un.length-1].created):'All caught up','','box')}${kpi('Available balance',money(S.seller.balance),'Next payout '+shortDate(S.seller.nextPayout),'','wallet')}${kpi('Account health',`<span class="okc">Healthy</span>`,'Order defect rate 0.4% (target < 1%)','','shield')}</div>
  <div class="grid c-main mt16"><div class="ocrd"><div class="ocrd-h"><h3>Sales, last 30 days</h3><span class="sm muted">Total ${money(vals.reduce((a,b)=>a+b,0))}</span></div>${barChart(vals,vals.map((_,i)=>dayLbl(29-i)))}</div>
   <div class="ocrd"><div class="ocrd-h"><h3>Action items</h3></div>${todo.map(([l,n,a,s])=>`<button class="row between" style="width:100%;padding:10px 0;border-bottom:1px solid var(--line-2);text-align:left" onclick="${a}"><span><span class="sm">${l}</span>${s&&n?`<br><span class="xs faint">${s}</span>`:''}</span><span class="row g4"><b style="color:${n?'var(--deal)':'var(--text-3)'}">${n}</b>${ic('chev','sm')}</span></button>`).join('')}</div></div>
  <div class="grid c-main mt16"><div class="ocrd"><div class="ocrd-h"><h3>Top listings</h3><a class="lnk sm" onclick="go('seller','listings')">Manage all</a></div>${top.length?`<div class="tbl-wrap" style="border:0"><table class="tbl"><thead><tr><th>Product</th><th class="num">Price</th><th class="num">Units / mo</th><th class="num">Available</th></tr></thead><tbody>${top.map(p=>`<tr class="click" onclick="UI.tmp.ep=null;go('seller','add',{id:'${p.id}'})"><td>${miniP(p,p.sku)}</td><td class="num">${money(p.price)}</td><td class="num">${num(p.bought)}</td><td class="num ${p.stock<=5?'errc b':''}">${p.stock}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No listings yet</div>'}</div>
   <div class="ocrd"><div class="ocrd-h"><h3>Account health</h3><span class="bdg ok">Healthy</span></div>${[['Order defect rate','0.4%','< 1%'],['Late shipment rate','1.2%','< 4%'],['Pre-fulfillment cancel rate','0.3%','< 2.5%'],['Valid tracking rate','99.1%','> 95%'],['Response time < 24 h','97%','> 90%']].map(([k,v,t])=>`<div class="kv sm" style="padding:6px 0;border-bottom:1px dashed var(--line-2)"><span>${k}<br><span class="xs faint">Target ${t}</span></span><b class="okc">${v}</b></div>`).join('')}
   <div class="alert info mt12">${ic('mega','sm')}<div><b>Holiday ship-by dates:</b> standard shipping orders placed by Dec 15 must ship within your handling time to arrive before Christmas.</div></div></div></div>`}};

/* ---------- Listings ---------- */
const LST={active:['Active','ok'],inactive:['Inactive','gray'],review:['Under review','warn'],removed:['Removed: policy','err']};
function inlineSet(id,k,v){const p=P(id);v=+v;if(isNaN(v)||v<0){toast('Enter a valid number','alert');return}
  if(k==='price'&&p.list&&v>=p.list)p.list=0;p[k]=k==='stock'?Math.round(v):+v.toFixed(2);toast(k==='price'?`Price updated to ${money(p[k])}. Shoppers see it within a minute.`:`Available quantity set to ${p[k]}`);render('seller');if(onStage('buyer'))render('buyer')}
SS.listings=p=>{const tab=p.tab||'all';const all=sProducts();const cnt=k=>all.filter(x=>x.status===k).length;
  const list=all.filter(x=>tab==='all'||x.status===tab||(tab==='oos'&&x.stock===0)).filter(x=>!p.q||norm(x.en+x.sku).includes(norm(p.q)));
  return{title:'Manage listings',sub:`${all.length} products · referral fees from the current fee schedule (${S.fees.updated})`,
  actions:`<button class="btn" onclick="go('seller','bulk')">${ic('upload','sm')} Bulk upload</button><button class="btn pri" onclick="UI.tmp.ep=null;go('seller','add')">${ic('plus','sm')} Add a product</button>`,
  body:`${tabs('seller','listings',[['all','All',all.length],['active','Active',cnt('active')],['inactive','Inactive',cnt('inactive')],['review','Under review',cnt('review')],['removed','Removed',cnt('removed')]],tab)}
  <div class="toolbar"><input class="input" placeholder="Search title or SKU" value="${esc(p.q||'')}" onkeydown="if(event.key==='Enter')go('seller','listings',{tab:'${tab}',q:this.value},true)"><span class="xs muted">Edit price and quantity directly in the table. Changes go live within a minute.</span></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Product</th><th>Status</th><th class="num">Available</th><th class="num">Price</th><th class="num">Fees / unit</th><th class="num">You receive</th><th></th></tr></thead><tbody>
  ${list.map(x=>{const f=feeCalc(x.price,x.cat);const st=LST[x.status];return `<tr><td>${miniP(x,`${x.sku} · ${cn(x.cat)}`)}</td><td><span class="bdg ${st[1]}">${st[0]}</span>${x.modNote?`<div class="xs errc mt4" style="max-width:220px">${esc(x.modNote)}</div>`:''}</td>
   <td class="num"><input class="input tnum" style="width:76px;min-height:30px;text-align:right" value="${x.stock}" onchange="inlineSet('${x.id}','stock',this.value)" aria-label="Available quantity"></td>
   <td class="num"><input class="input tnum" style="width:92px;min-height:30px;text-align:right" value="${x.price.toFixed(2)}" onchange="inlineSet('${x.id}','price',this.value)" aria-label="Price"></td>
   <td class="num">${money(f.total)}<div class="xs faint">${f.pct.toFixed(1)}%</div></td><td class="num"><b>${money(f.net)}</b></td>
   <td class="num"><button class="btn sm" onclick="UI.tmp.ep=null;go('seller','add',{id:'${x.id}'})">${ic('edit','sm')} Edit</button> ${['active','inactive'].includes(x.status)?`<button class="btn sm" onclick="P('${x.id}').status=P('${x.id}').status==='active'?'inactive':'active';toast(P('${x.id}').status==='active'?'Listing is active':'Listing deactivated');render('seller');if(onStage('buyer'))render('buyer')">${x.status==='active'?'Deactivate':'Activate'}</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="7"><div class="empty"><div class="art">${ic('list','xl')}</div>No listings here.<button class="btn pri" onclick="UI.tmp.ep=null;go('seller','add')">Add a product</button></div></td></tr>`}</tbody></table></div>`}};

/* ---------- Add / edit product ---------- */
const BANNED=/replica|1:1|knock ?off|counterfeit|\bfake\b|super ?copy|hàng nhái|\bnhái\b|dupe/i;
const TR_DEMO={'rice':'Nồi cơm','cooker':'điện','pot':'nồi','coffee':'cà phê','tea':'trà','stainless':'inox','set':'bộ'};
function epDraft(p){if(UI.tmp.ep&&UI.tmp.ep._id===(p.id||'new'))return UI.tmp.ep;const x=p.id&&P(p.id);
  UI.tmp.ep=x?{_id:x.id,en:x.en,vi:x.vi||'',brand:x.brand,cat:x.cat,upc:x.upc,price:x.price,list:x.list||'',cost:x.cost,stock:x.stock,sku:x.sku,weight:x.weight,variants:x.variants.join(', '),bul:(BULLETS[x.cat]||[]).map(b=>b[0]),desc:'',imgs:photos(x).length,comply:true,handling:S.seller.settings.handling}
   :{_id:'new',en:'',vi:'',brand:SL(myShop()).name.replace(/\s+(Co\.|LLC|Inc\.|Supply)$/,''),cat:'kitchen',upc:'',price:'',list:'',cost:'',stock:'',sku:'',weight:'',variants:'',bul:['','','',''],desc:'',imgs:0,comply:false,handling:S.seller.settings.handling};return UI.tmp.ep}
function epSet(k,v){UI.tmp.ep[k]=v;epSide()}
function epBul(i,v){UI.tmp.ep.bul[i]=v;epSide()}
function epSide(){const el=$$('.frame[data-role="seller"] #ep-side');el.forEach(e=>e.innerHTML=epSideHTML(UI.tmp.ep));$$('.frame[data-role="seller"] .ep-cnt').forEach(e=>e.textContent=(UI.tmp.ep.en||'').length+' / 200')}
function epQuality(d){const c=[[d.en.length>=40&&d.en.length<=200,'Title is 40–200 characters'],[d.imgs>=3,'At least 3 images (you have '+d.imgs+')'],[d.bul.filter(b=>b.trim()).length>=3,'At least 3 bullet points'],[!!d.upc||d.gtinEx,'UPC / GTIN or exemption'],[+d.price>0&&+d.stock>=0&&d.stock!=='','Price and quantity set'],[!!d.vi.trim(),'Vietnamese title for Tiếng Việt shoppers'],[d.comply,'Compliance confirmed']];return{c,score:Math.round(c.filter(x=>x[0]).length/c.length*100)}}
function epSideHTML(d){const price=+d.price||0,cost=+d.cost||0;const f=feeCalc(price,d.cat);const car=CARRIERS[0];const label=+(car.base+car.perLb*(+d.weight||1)).toFixed(2);const ship=price>=S.fees.freeShipMin?label:Math.max(0,label-S.fees.stdShip);
  const profit=f.net-cost-ship;const q=epQuality(d);const bad=BANNED.test(d.en+' '+d.vi);
  const fake={id:'pv',cat:d.cat,seller:myShop(),en:d.en||'Your product title',vi:d.vi||d.en||'Tên sản phẩm',price,list:+d.list>price?+d.list:0,rating:0,reviews:0,ph:PH[d.ph]?d.ph:({kitchen:'rice',coffee:'coffee',pantry:'cashew',beauty:'serum',fashion:'tee',baby:'bottle',electronics:'phones',home:'lamp'}[d.cat]),bought:0,stock:+d.stock||10,variants:[],status:'active'};
  return `<div class="ocrd"><div class="ocrd-h"><h3>Listing quality</h3></div><div class="score"><div class="ring" style="--p:${q.score}"><span>${q.score}</span></div><div class="sm">${q.score>=85?'<b class="okc">Great listing</b>':q.score>=60?'<b class="warnc">Good, can be better</b>':'<b class="errc">Needs work</b>'}<br><span class="xs muted">Complete listings get up to 2× more views in search.</span></div></div>
   <div class="chk-list mt12">${q.c.map(([ok,t])=>`<div class="${ok?'':'no'}">${ic(ok?'check':'x','sm')}${t}</div>`).join('')}</div>
   ${bad?`<div class="alert err mt12">${ic('alert','sm')}<div>Your title contains a restricted term (for example “replica” or “1:1”). The listing will go to manual review and may be removed.</div></div>`:''}</div>
  <div class="ocrd mt16"><div class="ocrd-h"><h3>Fees & profit, per unit</h3><span class="bdg info">Fee schedule ${S.fees.updated}</span></div>
   <div class="fee-row"><span>Sale price</span><b>${money(price)}</b></div>
   <div class="fee-row"><span>Referral fee · ${cn(d.cat)} (${f.refPct}%)</span><span>-${money(f.ref)}</span></div>
   <div class="fee-row"><span>Payment processing (${S.fees.procPct}% + ${money(S.fees.procFixed)})</span><span>-${money(f.proc)}</span></div>
   <div class="fee-row tot"><span>Your payout</span><span class="okc">${money(f.net)}</span></div>
   <div class="fee-row"><span>Est. shipping label · ${car.name}, ${+d.weight||1} lb${price<S.fees.freeShipMin?` (buyer pays ${money(S.fees.stdShip)})`:' (free for buyer)'}</span><span>-${money(ship)}</span></div>
   <div class="fee-row"><span>Your cost (private)</span><span>-${money(cost)}</span></div>
   <div class="fee-row tot"><span>Est. profit</span><span style="color:${profit>=0?'var(--ok)':'var(--err)'}">${profit<0?'-':''}${money(Math.abs(profit))}${price?` · ${Math.round(profit/price*100)}%`:''}</span></div>
   ${price&&profit<0?`<div class="alert err mt8">${ic('alert','sm')}<div>You lose money at this price. Break-even is about <b>${money((cost+ship+S.fees.procFixed)/(1-(f.refPct+S.fees.procPct)/100))}</b>.</div></div>`:''}
   ${+d.list&&+d.list>price?`<div class="alert info mt8">${ic('info','sm')}<div>The strikethrough “List” price only shows if shoppers paid it in the last 90 days (reference-price policy).</div></div>`:''}
   <p class="xs muted mt8">Sales tax is collected and remitted by EcomDemo. It is not part of your revenue and has no fee.</p></div>
  <div class="ocrd mt16"><div class="ocrd-h"><h3>Shopper preview</h3><span class="xs muted">Search result card</span></div><div style="width:220px;pointer-events:none;margin:0 auto">${pcard(fake,{atc:false})}</div></div>`}
SS.add=p=>{const d=epDraft(p);const x=p.id&&P(p.id);const f=(l,inner,help)=>`<div class="field"><label class="label">${l}</label>${inner}${help?`<div class="help">${help}</div>`:''}</div>`;
  const inp=(k,ph='',extra='')=>`<input class="input" value="${esc(d[k])}" placeholder="${esc(ph)}" oninput="epSet('${k}',this.value)" ${extra}>`;
  return{title:x?'Edit listing':'Add a product',sub:x?`${esc(x.sku)} · ${LST[x.status][0]}`:'Fill in the details below. Fees and profit update as you type.',
  actions:`<button class="btn" onclick="UI.tmp.ep=null;back('seller')">Cancel</button><button class="btn" onclick="toast('Draft saved')">Save as draft</button><button class="btn pri" onclick="saveListing()">${x?'Save and publish':'Publish listing'}</button>`,
  body:`<div class="grid c-main" style="align-items:start"><div class="col" style="gap:16px">
   <div class="ocrd"><div class="ocrd-h"><h3>1. Product identity</h3></div>
    ${f('Product title *',`<input class="input" value="${esc(d.en)}" placeholder="Brand + product type + key feature + size, e.g. Digital Rice Cooker 10-Cup with Fuzzy Logic" oninput="epSet('en',this.value)" maxlength="200">`,`<span class="ep-cnt">${d.en.length} / 200</span> · Do not use promotional words like “best” or “sale”.`)}
    ${f('Vietnamese title <span class="bdg brand">Shown when shoppers browse in Tiếng Việt</span>',`<div class="row g8"><input class="input" id="ep-vi" value="${esc(d.vi)}" placeholder="Ví dụ: Nồi cơm điện tử 10 cốc Fuzzy Logic" oninput="epSet('vi',this.value)"><button class="btn sm" onclick="autoVi()">${ic('globe','sm')} Auto-translate</button></div>`,'Machine translation is a starting point. Please review it before publishing.')}
    <div class="grid c3" style="gap:12px">${f('Brand *',inp('brand'))}${f('Category *',`<select class="select" onchange="epSet('cat',this.value)">${CATS.map(c=>`<option value="${c.id}" ${d.cat===c.id?'selected':''}>${c.en} · ${S.fees.cats[c.id]}%</option>`).join('')}</select>`)}${f('UPC / GTIN',inp('upc','12 digits',"inputmode='numeric'"),`<label class="row g4"><input type="checkbox" ${d.gtinEx?'checked':''} onchange="epSet('gtinEx',this.checked)"> I have a GTIN exemption</label>`)}</div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>2. Images</h3><span class="xs muted">${d.imgs} / 9 · JPEG or PNG, at least 1000 px, white background for the main image</span></div>
    <div class="row wrap">${Array.from({length:d.imgs},(_,i)=>`<div style="width:92px;position:relative">${img((PH[{kitchen:'rice',coffee:'coffee',pantry:'cashew',beauty:'serum',fashion:'tee',baby:'bottle',electronics:'phones',home:'lamp'}[d.cat]]||[])[i%3],200,'','',200).replace('class="img ','class="img " style="width:92px;height:92px;border-radius:8px" data-x="')}${i===0?'<span class="bdg dark" style="position:absolute;left:4px;bottom:4px">MAIN</span>':''}</div>`).join('')}
    ${d.imgs<9?`<button class="drop" style="width:92px;height:92px;padding:0;display:grid;place-items:center;font-size:11px" onclick="UI.tmp.ep.imgs++;render('seller')">${ic('camera')}<span>Add image</span></button>`:''}</div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>3. Description</h3></div>
    <label class="label">Key product features (bullet points) *</label>${d.bul.map((b,i)=>`<input class="input mb8" value="${esc(b)}" placeholder="Feature ${i+1}" oninput="epBul(${i},this.value)">`).join('')}
    ${f('Variations',`<input class="input" value="${esc(d.variants)}" placeholder="e.g. White, Black" oninput="UI.tmp.ep.variants=this.value">`,'Separate options with commas. Each option gets its own SKU automatically.')}
    ${f('Product description',`<textarea class="textarea" oninput="UI.tmp.ep.desc=this.value">${esc(d.desc)}</textarea>`)}</div>
   <div class="ocrd"><div class="ocrd-h"><h3>4. Offer</h3></div><div class="grid c3" style="gap:12px">
    ${f('Your price (USD) *',inp('price','0.00',"inputmode='decimal'"))}${f('List price (MSRP)',inp('list','Optional',"inputmode='decimal'"))}${f('Your cost <span class="faint">(private)</span>',inp('cost','0.00',"inputmode='decimal'"))}
    ${f('Quantity *',inp('stock','0',"inputmode='numeric'"))}${f('Seller SKU',inp('sku','Auto-generated if empty'))}${f('Condition',`<select class="select"><option>New</option></select>`)}</div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>5. Shipping & compliance</h3></div><div class="grid c3" style="gap:12px">
    ${f('Package weight (lb) *',inp('weight','0.0',"inputmode='decimal'"))}${f('Dimensions (in)',`<input class="input" placeholder="L × W × H" value="12 × 10 × 8">`)}${f('Handling time',`<select class="select" onchange="UI.tmp.ep.handling=+this.value">${[1,2,3].map(n=>`<option value="${n}" ${d.handling===n?'selected':''}>${n} business day${n>1?'s':''}</option>`).join('')}</select>`)}</div>
    ${f('Shipping template',`<select class="select"><option>Standard · FREE over $35, otherwise $5.99 · Expedited $9.99</option></select>`)}
    <label class="row g8 sm start"><input type="checkbox" ${d.comply?'checked':''} onchange="epSet('comply',this.checked)" style="margin-top:3px"> <span>This product meets all applicable US requirements (for example CPSC for children's products, FDA for food and cosmetics, FCC for electronics) and is not counterfeit.</span></label>
    <label class="row g8 sm start mt8"><input type="checkbox" style="margin-top:3px"> <span>This product requires a California Proposition 65 warning.</span></label></div>
  </div><div id="ep-side" style="position:sticky;top:0">${epSideHTML(d)}</div></div>`}};
function autoVi(){const d=UI.tmp.ep;if(!d.en.trim()){toast('Enter an English title first','alert');return}
  const known=S.products.find(x=>x.en===d.en);d.vi=known?known.vi:d.en.split(' ').map(w=>TR_DEMO[w.toLowerCase()]||w).join(' ');$$('#ep-vi').forEach(e=>e.value=d.vi);epSide();toast('Draft translation added. Please review it.','globe')}
function saveListing(){const d=UI.tmp.ep;const miss=[];if(!d.en.trim())miss.push('title');if(!(+d.price>0))miss.push('price');if(d.stock===''||isNaN(+d.stock))miss.push('quantity');if(!d.imgs)miss.push('at least 1 image');if(!(+d.weight>0))miss.push('weight');
  if(miss.length){toast('Missing: '+miss.join(', '),'alert');return}
  const bad=BANNED.test(d.en+' '+d.vi);let x=d._id!=='new'&&P(d._id);const isNew=!x;
  if(!x){const id='n'+Date.now().toString(36);x={id,seller:myShop(),rating:0,reviews:0,bought:0,created:Date.now(),upc:d.upc||'',ph:{kitchen:'rice',coffee:'coffee',pantry:'cashew',beauty:'serum',fashion:'tee',baby:'bottle',electronics:'phones',home:'lamp'}[d.cat],flag:null};S.products.push(x)}
  const price=+(+d.price).toFixed(2);if(!isNew&&price<x.price)x.low30=price;
  Object.assign(x,{en:d.en.trim(),vi:d.vi.trim()||d.en.trim(),brand:d.brand||SL(myShop()).name,cat:d.cat,price,list:+d.list>price?+(+d.list).toFixed(2):0,cost:+d.cost||0,stock:Math.round(+d.stock),weight:+d.weight,variants:d.variants.split(',').map(s=>s.trim()).filter(Boolean),sku:d.sku||x.sku||(SL(myShop()).mono+'-'+x.id.toUpperCase()),upc:d.upc||x.upc});
  if(isNew)x.low30=price;
  if(bad){x.status='review';x.modNote='Restricted term in title. Under manual review.';S.flags.unshift({id:'FL-'+(882+S.flags.length),pid:x.id,reason:'Restricted keyword found when the listing was published',src:'Listing publish check',sev:'High',status:'open',created:Date.now()});notify('admin',`Listing sent to review: <b>${esc(x.en)}</b>`,['moderation',{}]);toast('Listing saved and sent to manual review','alert')}
  else{if(x.status!=='inactive')x.status='active';x.modNote=null;toast(isNew?'Published. Your product is live on EcomDemo.':'Changes published')}
  UI.tmp.ep=null;go('seller','listings',{tab:'all'});if(onStage('buyer'))render('buyer');if(onStage('admin'))render('admin')}

/* ---------- Bulk upload ---------- */
const BULK_ROWS=[
 {sku:'SK-PHO20',en:'Stainless Steel Pho Stock Pot, 20 Qt',vi:'Nồi nấu phở inox 20 Qt',cat:'kitchen',price:64.99,stock:40,ph:'kettle',st:'ok',msg:'Ready'},
 {sku:'SK-CHOP10',en:'Natural Bamboo Chopsticks, 10 Pairs',vi:'Đũa tre tự nhiên, 10 đôi',cat:'kitchen',price:9.99,stock:300,ph:'spice',st:'ok',msg:'Ready'},
 {sku:'SK-PHIN1',en:'Stainless Phin Coffee Filter, 8 oz',vi:'Phin cà phê inox 8 oz',cat:'kitchen',price:11.99,stock:150,ph:'coffee',st:'ok',msg:'Ready'},
 {sku:'SK-HOTPOT',en:'Electric Hot Pot with Divider, 5 Qt',vi:'Nồi lẩu điện 2 ngăn 5 Qt',cat:'kitchen',price:54.99,stock:25,ph:'fry7',st:'warn',msg:'No UPC. Published under brand GTIN exemption.'},
 {sku:'SK-RC-X',en:'Rice Cooker Premium Brand 1:1 Replica',vi:'Nồi cơm hàng hiệu replica',cat:'kitchen',price:39.99,stock:10,ph:'rice',st:'err',msg:'Restricted term “replica”. Row not published.'},
];
SS.bulk=p=>{const st=p.st||'start';return{title:'Bulk upload',sub:'Add or update many listings at once with a spreadsheet',
  body:`<div class="steps"><div class="${st==='start'?'cur':'done'}"><i>1</i>Download template</div><div class="${st==='start'?'':st==='check'?'cur':'done'}"><i>2</i>Upload & check</div><div class="${st==='done'?'cur':''}"><i>3</i>Publish</div></div>
  ${st==='start'?`<div class="grid c2"><div class="ocrd"><h3 class="md bb">Get the template</h3><p class="sm muted mt8">One row per product. Required columns: sku, title, category, price, quantity, weight_lb, image_url_1. Optional: title_vi, upc, list_price, bullet_1…5.</p><div class="row g8 mt12"><button class="btn" onclick="dlTemplate()">${ic('download','sm')} CSV template</button><button class="btn" onclick="dlTemplate()">${ic('download','sm')} Excel template</button></div><p class="xs faint mt12">Up to 10,000 rows per file. We validate every row before anything goes live.</p></div>
   <button class="drop" onclick="go('seller','bulk',{st:'loading'},true);setTimeout(()=>go('seller','bulk',{st:'check'},true),900)" style="cursor:pointer">${ic('upload','xl')}<div class="md b mt8">Drop your file here or click to choose</div><div class="xs mt4">.csv, .xlsx · max 50 MB</div><div class="xs faint mt12">Demo: uses a sample file with 5 rows</div></button></div>`
  :st==='loading'?`<div class="ocrd center col" style="align-items:center;padding:40px"><div class="spinner"></div><b class="mt12">Checking ecomdemo_listings_oct.csv…</b><span class="xs muted">Validating categories, prices, images and restricted terms</span></div>`
  :`<div class="row g12 wrap mb12"><span class="bdg ok">${BULK_ROWS.filter(r=>r.st==='ok').length} ready</span><span class="bdg warn">${BULK_ROWS.filter(r=>r.st==='warn').length} warning</span><span class="bdg err">${BULK_ROWS.filter(r=>r.st==='err').length} error</span><span class="sm muted">ecomdemo_listings_oct.csv · 5 rows</span><span class="grow"></span>${st==='check'?`<button class="btn" onclick="go('seller','bulk',{},true)">Upload a different file</button><button class="btn pri" onclick="publishBulk()">Publish ${BULK_ROWS.filter(r=>r.st!=='err').length} listings</button>`:`<button class="btn pri" onclick="go('seller','listings')">View listings</button>`}</div>
   ${st==='done'?`<div class="alert ok mb12">${ic('check','sm')}<div><b>${BULK_ROWS.filter(r=>r.st!=='err').length} listings published.</b> 1 row was skipped. Download the error report to fix and re-upload it.</div></div>`:''}
   <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Row</th><th>SKU</th><th>Title</th><th>Category</th><th class="num">Price</th><th class="num">Qty</th><th>Result</th></tr></thead><tbody>${BULK_ROWS.map((r,i)=>`<tr><td>${i+2}</td><td class="tnum">${r.sku}</td><td>${esc(r.en)}<div class="xs faint">${esc(r.vi)}</div></td><td>${cn(r.cat)}</td><td class="num">${money(r.price)}</td><td class="num">${r.stock}</td><td><span class="bdg ${r.st==='ok'?'ok':r.st}">${r.st==='ok'?'Ready':r.st==='warn'?'Warning':'Error'}</span><div class="xs muted mt4" style="max-width:260px">${r.msg}</div></td></tr>`).join('')}</tbody></table></div>`}`}};
function dlTemplate(){const csv='sku,title,title_vi,category,price,list_price,quantity,weight_lb,upc,image_url_1,bullet_1\nSK-0001,Example product title,Tên sản phẩm,kitchen,19.99,,100,1.2,012345678905,https://...,Key feature\n';
  try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='ecomdemo_listing_template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}catch(e){}toast('Template downloaded','download')}
function publishBulk(){BULK_ROWS.filter(r=>r.st!=='err').forEach(r=>{if(S.products.some(p=>p.sku===r.sku))return;S.products.push({id:'b'+r.sku.toLowerCase().replace(/[^a-z0-9]/g,''),cat:r.cat,seller:myShop(),en:r.en,vi:r.vi,price:r.price,list:0,rating:0,reviews:0,ph:r.ph,brand:SL(myShop()).name,variants:[],bought:0,flag:null,stock:r.stock,sku:r.sku,status:'active',created:Date.now(),weight:2,cost:r.price*.5,upc:'',low30:r.price})});
  toast('4 listings published','check');go('seller','bulk',{st:'done'},true);if(onStage('buyer'))render('buyer')}

/* ---------- Orders ---------- */
function shipBy(o){return addBiz(o.created,S.seller.settings.handling)}
SS.orders=p=>{const tab=p.tab||'unshipped';const os=sOrders();const map={unshipped:['unshipped'],shipped:['shipped'],delivered:['delivered'],returns:['return_requested','refunded'],cancelled:['cancelled'],all:null};
  const list=os.filter(o=>!map[tab]||map[tab].includes(o.status)).filter(o=>!p.q||o.id.includes(p.q)||norm(o.buyer.name).includes(norm(p.q)));UI.tmp.sel=(UI.tmp.sel||[]).filter(id=>list.some(o=>o.id===id));const sel=UI.tmp.sel;
  const T=[['unshipped','Unshipped'],['shipped','Shipped'],['delivered','Delivered'],['returns','Returns'],['cancelled','Cancelled'],['all','All']].map(([k,l])=>[k,l,os.filter(o=>!map[k]||map[k].includes(o.status)).length]);
  return{title:'Manage orders',sub:'Ship each order by its ship-by date to keep your late shipment rate under 4%',
  actions:sel.length&&tab==='unshipped'?`<span class="sm muted">${sel.length} selected</span><button class="btn pri" onclick="bulkLabels()">${ic('print','sm')} Buy ${sel.length} labels (USPS)</button>`:`<button class="btn" onclick="exportOrders()">${ic('download','sm')} Order report</button>`,
  body:`${tabs('seller','orders',T,tab)}<div class="toolbar"><input class="input" placeholder="Search order ID or buyer" value="${esc(p.q||'')}" onkeydown="if(event.key==='Enter')go('seller','orders',{tab:'${tab}',q:this.value},true)"></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr>${tab==='unshipped'?'<th style="width:34px"></th>':''}<th>Order</th><th>Product</th><th>Ship to</th><th>${tab==='unshipped'?'Ship by':'Status'}</th><th class="num">Order total</th><th class="num">You receive</th><th></th></tr></thead><tbody>
  ${list.map(o=>{const x=P(o.items[0].pid);const n=orderNet(o);const on=sel.includes(o.id);const late=o.status==='unshipped'&&Date.now()>shipBy(o);
   return `<tr class="click ${o.isNew?'hl':''}" onclick="go('seller','order',{id:'${o.id}'})">${tab==='unshipped'?`<td onclick="event.stopPropagation()"><button class="chk ${on?'on':''}" onclick="const a=UI.tmp.sel,i=a.indexOf('${o.id}');i<0?a.push('${o.id}'):a.splice(i,1);render('seller')" aria-label="Select">${on?ic('check','sm'):''}</button></td>`:''}
   <td><b class="tnum">${o.id}</b>${o.isNew?' <span class="bdg deal">New</span>':''}<div class="xs faint">${ago(o.created)}</div></td><td>${miniP(x,`${o.items[0].v?esc(o.items[0].v)+' · ':''}Qty ${o.items[0].q}${o.items.length>1?` · +${o.items.length-1} more`:''}`)}</td>
   <td class="sm">${esc(o.buyer.name)}<div class="xs faint">${esc(o.buyer.city)}, ${o.buyer.state} · ${o.shipMethod==='exp'?'<b class="warnc">Expedited</b>':'Standard'}</div></td>
   <td class="sm">${o.status==='unshipped'?`<b class="${late?'errc':''}">${dayShort(shipBy(o))}</b>${late?'<div class="xs errc">Late</div>':''}`:`<span class="bdg ${STATUS[o.status][2]}">${STATUS[o.status][0]}</span>`}</td>
   <td class="num">${money(subOf(o)+o.shipCost-(o.promo||0))}<div class="xs faint">+ ${money(o.tax)} tax</div></td><td class="num"><b>${money(n.net)}</b></td>
   <td class="num" onclick="event.stopPropagation()">${o.status==='unshipped'?`<button class="btn pri sm" onclick="go('seller','order',{id:'${o.id}'})">Buy label</button>`:o.status==='return_requested'&&o.returnReq.status==='requested'?`<button class="btn sm" onclick="go('seller','returns')">Respond</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="8"><div class="empty"><div class="art">${ic('box','xl')}</div>No orders in this view</div></td></tr>`}</tbody></table></div>`}};
function rateFor(car,w){return +(car.base+car.perLb*w).toFixed(2)}
function orderWeight(o){return +o.items.reduce((a,i)=>a+P(i.pid).weight*i.q,0).toFixed(1)}
SS.order=p=>{const o=S.orders.find(x=>x.id===p.id);if(!o)return SS.orders({});o.isNew=false;const n=orderNet(o);const f=feeCalc(subOf(o)-(o.promo||0)+o.shipCost,P(o.items[0].pid).cat);const w=orderWeight(o);UI.tmp.car=UI.tmp.car||(o.shipMethod==='exp'?'fedex':'usps');
  return{title:`Order ${o.id}`,sub:`Placed ${new Date(o.created).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · ${o.shipMethod==='exp'?'Expedited (2-day)':'Standard'} shipping`,
  actions:`${stBdg(o.status).replace(/>.*</,'>'+STATUS[o.status][0]+'<')}${o.status==='unshipped'?`<button class="btn danger" onclick="sCancel('${o.id}')">Cancel order</button>`:''}<button class="btn" onclick="toast('Message sent through Buyer-Seller Messaging. Buyer email stays private.','chat')">${ic('chat','sm')} Contact buyer</button>`,
  body:`<div class="grid c-main" style="align-items:start"><div class="col" style="gap:16px">
   <div class="ocrd"><div class="grid c3"><div class="sm"><div class="xs faint">Ship by</div><b>${fmtDate(shipBy(o))}</b></div><div class="sm"><div class="xs faint">Deliver by</div><b>${fmtDate(o.eta)}</b></div><div class="sm"><div class="xs faint">Payment</div><b>${esc(o.pay)}</b><div class="xs okc">Authorized · captured on shipment</div></div></div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>Items</h3></div><div class="tbl-wrap" style="border:0"><table class="tbl"><thead><tr><th>Product</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Subtotal</th></tr></thead><tbody>${o.items.map(i=>{const x=P(i.pid);return `<tr><td>${miniP(x,`SKU ${x.sku}${i.v?' · '+esc(i.v):''}`)}</td><td class="num">${i.q}</td><td class="num">${money(i.price)}</td><td class="num">${money(i.price*i.q)}</td></tr>`}).join('')}</tbody></table></div>
    <div style="max-width:380px;margin-left:auto" class="mt12"><div class="fee-row"><span>Item subtotal</span><span>${money(subOf(o))}</span></div><div class="fee-row"><span>Shipping charged to buyer</span><span>${money(o.shipCost)}</span></div>${o.promo?`<div class="fee-row"><span>EcomDemo-funded promotion</span><span class="faint">${money(o.promo)} (paid by EcomDemo)</span></div>`:''}<div class="fee-row"><span>Sales tax <span class="faint">(collected and remitted by EcomDemo)</span></span><span class="faint">${money(o.tax)}</span></div>
     <div class="fee-row"><span>Referral fee (${f.refPct}%)</span><span>-${money(f.ref)}</span></div><div class="fee-row"><span>Payment processing</span><span>-${money(f.proc)}</span></div>${o.label?`<div class="fee-row"><span>Shipping label</span><span>-${money(o.label)}</span></div>`:''}<div class="fee-row tot"><span>You receive</span><span class="okc">${money(n.net+(o.promo||0))}</span></div></div></div>
   ${o.status==='unshipped'?`<div class="ocrd"><div class="ocrd-h"><h3>Buy a shipping label</h3><span class="xs muted">EcomDemo discounted rates · ships from ${esc(S.seller.settings.origin.split(',').slice(-2).join(','))}</span></div>
    <div class="grid c3" style="gap:12px"><div class="field"><label class="label">Weight</label><input class="input" value="${w} lb"></div><div class="field"><label class="label">Package</label><select class="select"><option>Box 12 × 10 × 8 in</option><option>Padded envelope</option></select></div><div class="field"><label class="label">Ship date</label><input class="input" value="${dayShort(Date.now())}"></div></div>
    ${CARRIERS.map(c=>{const r=rateFor(c,w);const on=UI.tmp.car===c.id;return `<button class="opt ${on?'on':''}" onclick="UI.tmp.car='${c.id}';render('seller')"><span class="rad ${on?'on':''}"></span><span class="grow sm"><b>${c.name}</b><br><span class="muted">${c.days}${c.id==='fedex'&&o.shipMethod==='exp'?' · <b class="warnc">Required for expedited</b>':''}</span></span><b>${money(r)}</b></button>`}).join('')}
    <div class="row between mt12 wrap g8"><span class="xs muted">Label cost is deducted from this order's payout. Tracking is uploaded to the buyer automatically.</span><button class="btn pri" onclick="buyLabel('${o.id}')">${ic('print','sm')} Buy label & confirm shipment</button></div></div>`:''}
   ${o.tracking?`<div class="ocrd"><div class="ocrd-h"><h3>Shipment</h3>${o.labelPdf?`<button class="btn sm" onclick="showLabel('${o.id}')">${ic('print','sm')} Reprint label</button>`:''}</div><div class="sm">${esc(o.carrier)} · <b class="tnum">${esc(o.tracking)}</b></div><div class="tl mt12">${o.log.map(l=>`<div><b>${LOGTXT[l.k][0]}</b><div class="xs muted">${new Date(l.t).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</div></div>`).join('')}</div></div>`:''}
  </div>
  <div class="col" style="gap:16px"><div class="ocrd"><div class="ocrd-h"><h3>Ship to</h3></div><div class="sm"><b>${esc(o.buyer.name)}</b><br>${esc(o.buyer.line1)}<br>${esc(o.buyer.city)}, ${o.buyer.state} ${o.buyer.zip}<br>United States</div><div class="xs okc mt8">✓ Address verified (USPS)</div><div class="xs muted mt8">Buyer phone and email are hidden. Use Buyer-Seller Messaging.</div></div>
   ${o.returnReq?`<div class="ocrd"><div class="ocrd-h"><h3>Return</h3><span class="bdg warn">${o.returnReq.status}</span></div><div class="sm">${esc(RET_REASONS.find(r=>r[0]===o.returnReq.reason)?.[1]||'')}</div><div class="sm muted mt4">“${esc(o.returnReq.comment)}”</div><button class="btn sm mt8" onclick="go('seller','returns')">Go to returns</button></div>`:''}
   <div class="ocrd"><div class="ocrd-h"><h3>Order history</h3></div><div class="tl">${o.log.map(l=>`<div><span class="sm">${LOGTXT[l.k][0]}</span><div class="xs muted">${ago(l.t)}</div></div>`).join('')}</div></div></div></div>`}};
function buyLabel(id){const o=S.orders.find(x=>x.id===id);const c=CARRIERS.find(x=>x.id===(UI.tmp.car||'usps'));const r=rateFor(c,orderWeight(o));
  o.status='shipped';o.carrier=c.name;o.label=r;o.labelPdf=true;o.tracking=c.id==='usps'?'9400 1'+String(Date.now()).slice(-15).replace(/(\d{4})/g,'$1 ').trim():c.id==='ups'?'1Z'+String(Date.now()).slice(-12)+'03':String(Date.now()).slice(-12);
  o.log.unshift({t:Date.now()+60e3,k:'transit'});o.log.unshift({t:Date.now(),k:'shipped'});o.log.sort((a,b)=>b.t-a.t);o.eta=c.id==='fedex'?etaExp():addBiz(Date.now(),3);UI.tmp.car=null;
  render('seller');if(onStage('buyer'))render('buyer');showLabel(id);toast('Label purchased. Tracking sent to the buyer.','truck')}
function showLabel(id){const o=S.orders.find(x=>x.id===id);const sh=SL(o.seller);
  openOv('seller',`<div class="modal">${mHead('seller','Shipping label · 4 × 6 in')}<div class="modal-b"><div class="label-sheet print-area"><div class="r" style="display:flex;justify-content:space-between"><b>${esc(o.carrier.split(' ')[0])}</b><b>${o.carrier.includes('2Day')?'2':'G'}</b></div><div class="r xs">FROM: ${esc(sh.name)}<br>${esc(S.seller.settings.origin)}</div><div class="r"><div class="xs">SHIP TO:</div><b style="font-size:15px">${esc(o.buyer.name.toUpperCase())}<br>${esc(o.buyer.line1.toUpperCase())}<br>${esc(o.buyer.city.toUpperCase())} ${o.buyer.state} ${o.buyer.zip}</b></div><div class="r"><div class="barcode"></div><div class="center b">${esc(o.tracking)}</div></div><div class="r xs" style="border:0">Order ${o.id} · ${o.items.reduce((a,i)=>a+i.q,0)} item(s) · ${orderWeight(o)} lb</div></div></div>
  <div class="modal-f"><button class="btn" onclick="closeOv('seller')">Close</button><button class="btn pri" onclick="window.print()">${ic('print','sm')} Print</button></div></div>`)}
function bulkLabels(){const ids=[...UI.tmp.sel];ids.forEach(id=>{UI.tmp.car='usps';const o=S.orders.find(x=>x.id===id);const c=CARRIERS[0];o.status='shipped';o.carrier=c.name;o.label=rateFor(c,orderWeight(o));o.labelPdf=true;o.tracking='9400 1'+String(Date.now()+Math.random()*1e6|0).slice(-15).replace(/(\d{4})/g,'$1 ').trim();o.log.unshift({t:Date.now(),k:'shipped'});o.eta=addBiz(Date.now(),3);o.isNew=false});
  UI.tmp.sel=[];UI.tmp.car=null;toast(`${ids.length} labels purchased. Download the PDF to print them together.`,'print');render('seller');if(onStage('buyer'))render('buyer')}
function sCancel(id){openOv('seller',`<div class="modal">${mHead('seller','Cancel order')}<div class="modal-b"><div class="alert warn">${ic('alert','sm')}<div>Seller cancellations count toward your pre-fulfillment cancel rate (target under 2.5%). The buyer is refunded in full.</div></div><div class="field mt12"><label class="label">Reason</label><select class="select" id="sc-r"><option>Out of stock</option><option>Pricing error</option><option>Cannot ship to this address</option><option>Buyer requested cancellation</option></select></div></div><div class="modal-f"><button class="btn" onclick="closeOv('seller')">Keep order</button><button class="btn pri" onclick="const o=S.orders.find(x=>x.id==='${id}');o.status='cancelled';o.cancelReason='Seller: '+$('#sc-r').value;o.log.unshift({t:Date.now(),k:'cancelled'});o.items.forEach(i=>P(i.pid).stock+=i.q);UI.ov.seller=null;toast('Order cancelled. Buyer refunded.');render('seller');if(onStage('buyer'))render('buyer')">Cancel order</button></div></div>`)}
function exportOrders(){const rows=[['order_id','date','buyer_state','status','items_subtotal','shipping','tax_collected_by_ecomdemo','your_payout']].concat(sOrders().map(o=>[o.id,new Date(o.created).toISOString().slice(0,10),o.buyer.state,o.status,subOf(o).toFixed(2),o.shipCost.toFixed(2),o.tax.toFixed(2),orderNet(o).net.toFixed(2)]));
  try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));a.download='orders_report.csv';a.click()}catch(e){}toast('Order report downloaded','download')}

/* ---------- Returns ---------- */
SS.returns=()=>{const rs=sOrders().filter(o=>o.returnReq);const cl=S.claims.filter(c=>c.seller===myShop());
  return{title:'Returns & claims',sub:'Respond to return requests within 48 hours. Unanswered requests are approved automatically.',
  body:`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Order</th><th>Item</th><th>Reason & comment</th><th>Requested</th><th>Status</th><th></th></tr></thead><tbody>
  ${rs.map(o=>{const r=o.returnReq;const x=P(r.items[0]);const seller=['defective','not_described','wrong','damaged'].includes(r.reason);return `<tr><td><a class="lnk b tnum" onclick="go('seller','order',{id:'${o.id}'})">${o.id}</a><div class="xs faint">${esc(o.buyer.name)}</div></td><td>${miniP(x,money(subOf(o)))}</td><td class="sm" style="max-width:280px"><b>${esc(RET_REASONS.find(z=>z[0]===r.reason)?.[1]||r.reason)}</b>${seller?' <span class="bdg warn">Seller fault</span>':''}<div class="muted">“${esc(r.comment||'—')}”</div></td><td class="sm">${ago(r.created)}${r.status==='requested'?`<div class="xs warnc">${Math.max(1,Math.round(48-(Date.now()-r.created)/HR))} h left</div>`:''}</td>
   <td><span class="bdg ${{requested:'warn',approved:'info',rejected:'err',refunded:'ok'}[r.status]}">${{requested:'Awaiting response',approved:'Label issued',rejected:'Declined',refunded:'Refunded'}[r.status]}</span></td>
   <td class="num">${r.status==='requested'?`<button class="btn pri sm" onclick="retAuth('${o.id}')">Authorize</button> <button class="btn sm" onclick="retDecline('${o.id}')">Decline</button>`:r.status==='approved'?`<button class="btn pri sm" onclick="retRefund('${o.id}')">Item received · refund</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="6"><div class="empty">No return requests</div></td></tr>`}</tbody></table></div>
  <h2 class="md bb mt24 mb12">A-to-z Guarantee claims</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Claim</th><th>Order</th><th>Reason</th><th class="num">Amount</th><th>Status</th></tr></thead><tbody>${cl.map(c=>`<tr><td><b>${c.id}</b><div class="xs faint">${ago(c.created)}</div></td><td class="tnum">${c.order}</td><td class="sm">${esc(c.reason)}<div class="muted xs">${esc(c.detail)}</div></td><td class="num">${money(c.amount)}</td><td><span class="bdg ${c.status==='open'?'warn':c.status==='refunded'?'err':'ok'}">${c.status==='open'?'Under EcomDemo review':c.status==='refunded'?'Granted to buyer':'Decided in your favor'}</span></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">No claims. Keep it up!</div></td></tr>`}</tbody></table></div>`}};
function retAuth(id){const o=S.orders.find(x=>x.id===id);o.returnReq.status='approved';o.log.unshift({t:Date.now(),k:'return_approved'});toast('Return authorized. Prepaid UPS QR code sent to the buyer.','return');render('seller');if(onStage('buyer'))render('buyer')}
function retDecline(id){openOv('seller',`<div class="modal">${mHead('seller','Decline return')}<div class="modal-b"><div class="alert warn">${ic('alert','sm')}<div>Returns within 30 days for defective or not-as-described items cannot be declined. The buyer can file an A-to-z claim, which affects your order defect rate.</div></div><div class="field mt12"><label class="label">Message to buyer</label><textarea class="textarea" id="rd-n">Item shows signs of misuse. We can offer a replacement part instead.</textarea></div></div><div class="modal-f"><button class="btn" onclick="closeOv('seller')">Back</button><button class="btn pri" onclick="const o=S.orders.find(x=>x.id==='${id}');o.returnReq.status='rejected';o.returnReq.sellerNote=$('#rd-n').value;o.log.unshift({t:Date.now(),k:'return_rejected'});UI.ov.seller=null;toast('Return declined');render('seller');if(onStage('buyer'))render('buyer')">Decline return</button></div></div>`)}
function retRefund(id){const o=S.orders.find(x=>x.id===id);o.returnReq.status='refunded';o.status='refunded';o.refund=+(subOf(o)+o.tax).toFixed(2);o.log.unshift({t:Date.now(),k:'refunded'});o.items.forEach(i=>P(i.pid).stock+=i.q);S.seller.balance=Math.max(0,S.seller.balance-orderNet(o).net);
  toast(`Refunded ${money(o.refund)} to the buyer`,'wallet');render('seller');if(onStage('buyer'))render('buyer')}

/* ---------- Payments ---------- */
SS.payments=()=>{const os=sOrders().filter(o=>['delivered','shipped','refunded'].includes(o.status));const tx=os.map(o=>({o,n:orderNet(o),f:feeCalc(subOf(o)-(o.promo||0)+o.shipCost,P(o.items[0].pid).cat)}));
  const fees30=tx.reduce((a,t)=>a+t.f.total,0),gross30=tx.reduce((a,t)=>a+t.f.gross,0),labels=tx.reduce((a,t)=>a+(t.o.label||0),0);
  return{title:'Payments',sub:'Payouts every 14 days to your verified bank account. Funds from an order are available after it ships.',
  actions:`<button class="btn" onclick="exportOrders()">${ic('download','sm')} Statement (CSV)</button>`,
  body:`<div class="grid c4">${kpi('Available balance',money(S.seller.balance),'','','wallet')}${kpi('Next payout',shortDate(S.seller.nextPayout),'To Chase Business •••• 6789')}${kpi('Fees, last 30 days',money(fees30),gross30?`${(fees30/gross30*100).toFixed(1)}% of sales`:'')}${kpi('Shipping labels, 30 days',money(labels),'Bought through EcomDemo')}</div>
  <div class="grid c-main mt16" style="align-items:start"><div class="ocrd"><div class="ocrd-h"><h3>Transactions</h3></div><div class="tbl-wrap" style="border:0"><table class="tbl"><thead><tr><th>Date</th><th>Order</th><th class="num">Sales</th><th class="num">Fees</th><th class="num">Label</th><th class="num">Net</th></tr></thead><tbody>
   ${tx.map(t=>`<tr><td class="sm">${shortDate(t.o.created)}</td><td class="tnum sm"><a class="lnk" onclick="go('seller','order',{id:'${t.o.id}'})">${t.o.id}</a>${t.o.status==='refunded'?' <span class="bdg err">Refund</span>':''}</td><td class="num">${money(t.f.gross)}</td><td class="num">-${money(t.f.total)}</td><td class="num">${t.o.label?'-'+money(t.o.label):'—'}</td><td class="num"><b class="${t.o.status==='refunded'?'errc':''}">${t.o.status==='refunded'?'-':''}${money(t.n.net)}</b></td></tr>`).join('')}</tbody></table></div></div>
  <div class="col" style="gap:16px"><div class="ocrd"><div class="ocrd-h"><h3>Payout history</h3></div>${S.seller.payouts.map(p=>`<div class="kv sm" style="padding:8px 0;border-bottom:1px dashed var(--line-2)"><span>${shortDate(p.d)}<br><span class="xs faint">ACH · Chase •••• 6789</span></span><b>${money(p.amt)}</b></div>`).join('')}</div>
   <div class="ocrd"><div class="ocrd-h"><h3>Tax documents</h3></div><div class="sm">W-9 on file · EIN ${esc(SL(myShop()).ein)}</div><div class="sm mt4">Form 1099-K for 2026 will be available by January 31, 2027.</div><p class="xs muted mt8">EcomDemo collects and remits sales tax in every state as a marketplace facilitator.</p></div></div></div>`}};

/* ---------- Customer questions ---------- */
SS.feedback=()=>{const qs=S.questions.filter(x=>P(x.pid)&&P(x.pid).seller===myShop());const open=qs.filter(x=>!x.a),done=qs.filter(x=>x.a);const rv=S.reviews.filter(r=>P(r.pid)&&P(r.pid).seller===myShop()&&r.stars<=3).slice(0,5);
  return{title:'Customer questions',sub:'Answers appear publicly on the product page. Reply in English or Tiếng Việt.',
  body:`<div class="grid c-main" style="align-items:start"><div class="col" style="gap:16px"><div class="ocrd"><div class="ocrd-h"><h3>Waiting for your answer (${open.length})</h3></div>${open.map(q=>{const i=S.questions.indexOf(q);return `<div style="padding:12px 0;border-bottom:1px solid var(--line-2)"><div class="xs faint">${esc(P(q.pid).en)} · ${ago(q.t)}</div><div class="sm b mt4">“${esc(q.q)}”</div><div class="row g8 mt8"><input class="input" id="qa-${i}" placeholder="Write a helpful answer…" style="min-height:34px"><button class="btn pri sm" onclick="const v=$('#qa-${i}').value.trim();if(!v)return;S.questions[${i}].a=v;S.questions[${i}].by=SL(myShop()).name;toast('Answer published on the product page');render('seller');if(onStage('buyer'))render('buyer')">Publish</button></div></div>`}).join('')||'<div class="empty">All questions answered</div>'}</div>
   <div class="ocrd"><div class="ocrd-h"><h3>Answered</h3></div>${done.map(q=>`<div style="padding:10px 0;border-bottom:1px solid var(--line-2)" class="sm"><div class="xs faint">${esc(P(q.pid).en)}</div><b>Q:</b> ${esc(q.q)}<br><b>A:</b> ${esc(q.a)}</div>`).join('')}</div></div>
  <div class="ocrd"><div class="ocrd-h"><h3>Recent critical reviews</h3></div><p class="xs muted mb8">You cannot reply publicly to reviews. Contact the buyer through messaging to resolve the issue.</p>${rv.map(r=>`<div style="padding:10px 0;border-bottom:1px solid var(--line-2)" class="sm">${stars(r.stars)} <b>${esc(r.title)}</b><div class="muted">${esc(r.text)}</div><div class="xs faint">${esc(P(r.pid).en.split(',')[0])}</div></div>`).join('')||'<div class="empty">No critical reviews</div>'}</div></div>`}};

/* ---------- Store settings ---------- */
SS.settings=()=>{const st=S.seller.settings;const sh=SL(myShop());return{title:'Store settings',sub:esc(sh.legal),actions:`<button class="btn pri" onclick="toast('Settings saved');render('seller');if(onStage('buyer'))render('buyer')">Save changes</button>`,
  body:`<div class="grid c2" style="align-items:start"><div class="col" style="gap:16px">
   <div class="ocrd"><div class="ocrd-h"><h3>Storefront</h3><a class="lnk sm" onclick="go('buyer','store',{id:'${sh.id}'})">View</a></div><div class="row g12 mb12">${mono(sh,'lg')}<button class="btn sm">${ic('upload','sm')} Upload logo</button></div>
    <div class="field"><label class="label">Store name</label><input class="input" value="${esc(sh.name)}"></div><div class="field"><label class="label">About (English)</label><textarea class="textarea">${esc(sh.about)}</textarea></div><div class="field"><label class="label">About (Tiếng Việt)</label><textarea class="textarea">${esc(sh.aboutVi)}</textarea></div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>Vacation mode</h3><button class="tgl ${st.vacation?'on':''}" onclick="S.seller.settings.vacation=!S.seller.settings.vacation;toast(S.seller.settings.vacation?'Vacation mode on. Your listings are hidden from shoppers.':'Vacation mode off. Listings are visible again.');render('seller');if(onStage('buyer'))render('buyer')" aria-label="Vacation mode"></button></div><p class="sm muted">Temporarily hide all listings without losing their ranking history.</p></div></div>
  <div class="col" style="gap:16px">
   <div class="ocrd"><div class="ocrd-h"><h3>Shipping</h3></div><div class="field"><label class="label">Ships from</label><input class="input" value="${esc(st.origin)}"></div><div class="grid c2" style="gap:12px"><div class="field"><label class="label">Handling time</label><select class="select" onchange="S.seller.settings.handling=+this.value">${[1,2,3].map(n=>`<option value="${n}" ${st.handling===n?'selected':''}>${n} business day${n>1?'s':''}</option>`).join('')}</select></div><div class="field"><label class="label">Same-day cutoff</label><input class="input" value="${esc(st.cutoff)}"></div></div><div class="sm">Carriers: USPS, UPS, FedEx · Free shipping threshold: ${money(S.fees.freeShipMin)} (marketplace default)</div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>Returns</h3></div><div class="sm">Return window: <b>${st.returns} days</b> (marketplace minimum). Prepaid return labels are charged to you only for seller-fault returns.</div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>Business & banking</h3><span class="bdg ok">Verified</span></div><div class="kv sm"><span>Legal name</span><b>${esc(sh.legal)}</b></div><div class="kv sm"><span>EIN</span><span>${esc(sh.ein)}</span></div><div class="kv sm"><span>Deposit account</span><span>Chase Business •••• 6789</span></div><div class="kv sm"><span>Tax form</span><span>W-9 · signed Mar 2, 2026</span></div></div>
   <div class="ocrd"><div class="ocrd-h"><h3>Users & permissions</h3><button class="btn sm">${ic('plus','sm')} Invite user</button></div>${[['Hung Nguyen','Owner · full access'],['Tram Le','Orders & shipping'],['Minh Vo','Catalog only']].map(([n,r])=>`<div class="row g8" style="padding:6px 0"><span class="avatar">${n.split(' ').map(x=>x[0]).join('')}</span><span class="sm grow">${n}<br><span class="xs faint">${r}</span></span></div>`).join('')}</div></div></div>`}};

/* ---------- Onboarding (KYB) ---------- */
const OB_STEPS=['Business','Owner identity','Bank & tax','Store','Review'];
function obD(){const o=S.seller.onboard;o.data=Object.assign({legal:'Bông Sen Foods LLC',entity:'LLC',ein:'12-3456789',state:'California',addr:'14291 Brookhurst St, Garden Grove, CA 92843',phone:'(714) 555-0170',owner:'Thanh Tran',dob:'1984-03-12',ssn:'4417',idDoc:false,routing:'322271627',acct:'000123456789',w9:false,store:'Bông Sen Foods',cats:['pantry','coffee'],skus:'50–200',lang:'Both'},o.data);return o.data}
function obSet(k,v){obD()[k]=v;save()}
SS.onboard=()=>{const o=S.seller.onboard;const d=obD();const st=o.step;
  if(o.status){const ap=S.apps.find(a=>a.id===o.appId);const s=ap?ap.status:'pending';return{title:'Register a new business',sub:esc(d.legal),body:`<div class="ocrd" style="max-width:760px">
   ${s==='approved'?`<div class="ok-hero">${ic('check')}<div><h2 class="xl bb okc">Your business is verified</h2><p class="sm mt4">${esc(d.store)} is approved to sell on EcomDemo. Add your first products to go live.</p><button class="btn pri mt12" onclick="S.seller.shop='${ap.sellerId}';go('seller','dashboard')">Open ${esc(d.store)} in Seller Central</button></div></div>`
   :s==='rejected'?`<div class="alert err">${ic('alert','sm')}<div><b>Application not approved.</b> ${esc(ap.note||'')}</div></div>`
   :s==='info'?`<div class="alert warn">${ic('alert','sm')}<div><b>More information needed:</b> ${esc(ap.note||'')}</div></div>`
   :`<div class="row g12 start"><div class="spinner" style="width:28px;height:28px;flex:none"></div><div><h2 class="lg bb">Application under review</h2><p class="sm muted mt4">Most applications are reviewed within 1 business day. We will email ${esc(d.owner.split(' ')[0].toLowerCase())}@bongsenfoods.example.</p></div></div>`}
   <div class="hr"></div><h3 class="md bb mb8">Verification checks</h3><div class="chk-list">${[['EIN matches IRS records (TIN match)',ap&&ap.checks.ein],['Owner identity: ID document + selfie',ap&&ap.checks.id],['Bank account ownership',ap&&ap.checks.bank],['Sanctions screening (OFAC)',ap&&ap.checks.ofac],['Business address',ap&&ap.checks.address],['Final review by EcomDemo team',s==='approved'?'pass':s==='pending'?'wait':'fail']].map(([t,v])=>`<div class="${v==='pass'?'':'no'}">${ic(v==='pass'?'check':v==='fail'?'x':'clock','sm')}${t}${v==='review'||v==='wait'?' <span class="xs faint">· in progress</span>':''}</div>`).join('')}</div>
   ${s==='pending'?`<div class="alert info mt16">${ic('info','sm')}<div><b>Prototype tip:</b> switch to <b>Admin → Seller applications</b> to approve this business.</div></div>`:''}
   ${s!=='pending'&&s!=='approved'?`<button class="btn mt12" onclick="S.seller.onboard={step:0,data:S.seller.onboard.data,status:null};render('seller')">Edit and resubmit</button>`:''}</div>`}}
  const f=(l,k,ph,extra='',help)=>`<div class="field"><label class="label">${l}</label><input class="input" value="${esc(d[k])}" placeholder="${esc(ph||'')}" oninput="obSet('${k}',this.value)" ${extra}>${help?`<div class="help">${help}</div>`:''}</div>`;
  const nav=`<div class="row between mt16"><button class="btn" ${st===0?'disabled':''} onclick="S.seller.onboard.step--;render('seller',true)">Back</button><button class="btn pri" onclick="${st<5?'S.seller.onboard.step++;render(\'seller\',true)':'submitOnboard()'}">${st===0?'Start registration':st<5?'Save and continue':'Submit for verification'}</button></div>`;
  const bodies=[
   `<div class="grid c2" style="align-items:start"><div class="ocrd"><h2 class="xl bb">Sell on EcomDemo</h2><p class="sm muted mt8">EcomDemo is open to registered US businesses. Registration takes about 15 minutes. Have these ready:</p>
    <div class="chk-list mt12">${['Business legal name, EIN and registered address','Government-issued photo ID for each owner with 25% or more','US bank account for payouts','Credit card for the monthly plan','Product categories and an estimate of your catalog size'].map(t=>`<div>${ic('check','sm')}${t}</div>`).join('')}</div></div>
    <div class="ocrd"><div class="ocrd-h"><h3>Professional plan</h3><span class="bdg ok">First month free</span></div><div class="xxl bb">${money(S.fees.plan)}<span class="sm muted" style="font-weight:400"> / month</span></div><p class="sm muted mt4">Plus a referral fee per item sold and payment processing (${S.fees.procPct}% + ${money(S.fees.procFixed)}).</p>
     <table class="tbl mt12"><thead><tr><th>Category</th><th class="num">Referral fee</th></tr></thead><tbody>${CATS.map(c=>`<tr><td>${c.en}</td><td class="num">${S.fees.cats[c.id]}%</td></tr>`).join('')}</tbody></table><p class="xs faint mt8">No listing fees, no fees on sales tax. Fee changes are announced 30 days in advance.</p></div></div>`,
   `<div class="ocrd" style="max-width:820px"><h3 class="md bb mb12">Business information</h3>${f('Legal business name (exactly as on IRS documents)','legal')}<div class="grid c2" style="gap:12px"><div class="field"><label class="label">Business type</label><select class="select" onchange="obSet('entity',this.value)">${['LLC','Corporation','Partnership','Sole proprietorship (with EIN)'].map(x=>`<option ${d.entity===x?'selected':''}>${x}</option>`).join('')}</select></div>${f('Employer Identification Number (EIN)','ein','XX-XXXXXXX',"inputmode='numeric'",'We verify this against IRS records. It is never shown publicly.')}</div><div class="grid c2" style="gap:12px">${f('State of registration','state')}${f('Business phone (we will text a code)','phone')}</div>${f('Registered business address','addr','','','No P.O. boxes.')}</div>`,
   `<div class="ocrd" style="max-width:820px"><h3 class="md bb">Primary contact & beneficial owners</h3><p class="sm muted mb12">Federal rules require us to verify everyone who owns 25% or more of the business.</p><div class="grid c2" style="gap:12px">${f('Full legal name','owner')}${f('Date of birth','dob','','type="date"')}</div><div class="grid c2" style="gap:12px">${f('SSN (last 4 digits)','ssn','','inputmode="numeric" maxlength="4"')}<div class="field"><label class="label">Ownership</label><select class="select"><option>100%</option><option>50%–99%</option><option>25%–49%</option></select></div></div>
    <div class="field"><label class="label">Photo ID</label><button class="drop" style="width:100%;padding:18px;${d.idDoc?'border-color:var(--ok);color:var(--ok)':''}" onclick="obSet('idDoc',true);render('seller');toast('ID and selfie captured. Identity check passed.','id')">${ic(d.idDoc?'check':'id','lg')}<div class="sm b mt4">${d.idDoc?"Driver's license verified · selfie match 98%":"Upload driver's license or passport, then take a selfie"}</div><div class="xs mt4">Processed by our identity verification partner. Images are encrypted and deleted after 30 days.</div></button></div>
    <a class="lnk sm">${ic('plus','sm')} Add another owner with 25% or more</a></div>`,
   `<div class="ocrd" style="max-width:820px"><h3 class="md bb mb12">Deposit account</h3><button class="opt on"><span class="rad on"></span><span class="sm grow"><b>Connect your bank instantly</b><br><span class="muted">Sign in to your bank through Plaid. Recommended.</span></span></button><button class="opt"><span class="rad"></span><span class="sm grow"><b>Enter routing and account number</b><br><span class="muted">We send two micro-deposits to confirm (1–2 days)</span></span></button>
    <div class="grid c2 mt12" style="gap:12px">${f('Routing number','routing')}${f('Account number','acct')}</div><div class="xs okc mb12">✓ Chase Bank N.A. · business checking · name matches ${esc(d.legal)}</div>
    <div class="hr"></div><h3 class="md bb mb8">Tax information</h3><button class="opt ${d.w9?'on':''}" onclick="obSet('w9',!obD().w9);render('seller')"><span class="chk ${d.w9?'on':''}">${d.w9?ic('check','sm'):''}</span><span class="sm grow"><b>Complete the W-9 tax interview</b><br><span class="muted">Signed electronically. Used to issue your annual Form 1099-K.</span></span>${d.w9?'<span class="bdg ok">Signed</span>':''}</button></div>`,
   `<div class="ocrd" style="max-width:820px"><h3 class="md bb mb12">Your store</h3>${f('Store name (shown to shoppers)','store','','','✓ Available')}
    <div class="field"><label class="label">What will you sell?</label><div class="chips wrap">${CATS.map(c=>`<button class="chip ${d.cats.includes(c.id)?'on':''}" onclick="const a=obD().cats,i=a.indexOf('${c.id}');i<0?a.push('${c.id}'):a.splice(i,1);render('seller')">${c.en}</button>`).join('')}</div>${d.cats.some(c=>['baby','pantry','beauty'].includes(c))?`<div class="help warnc">Some categories need extra documents (for example FDA facility registration for food, CPSC certificates for baby products). You can upload them later.</div>`:''}</div>
    <div class="grid c2" style="gap:12px"><div class="field"><label class="label">How many products?</label><select class="select" onchange="obSet('skus',this.value)">${['1–10','11–50','50–200','200–1,000','1,000+'].map(x=>`<option ${d.skus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label class="label">Customer support language</label><select class="select" onchange="obSet('lang',this.value)">${['English','Tiếng Việt','Both'].map(x=>`<option ${d.lang===x?'selected':''}>${x}</option>`).join('')}</select></div></div></div>`,
   `<div class="ocrd" style="max-width:820px"><h3 class="md bb mb12">Review your information</h3>${[['Business',`${d.legal} · ${d.entity} · ${d.state}`,1],['EIN',d.ein.replace(/^\d{2}-\d{3}/,'**-***'),1],['Address',d.addr,1],['Owner',`${d.owner} · ID ${d.idDoc?'verified':'<b class="errc">missing</b>'}`,2],['Bank',`Chase •••• ${String(d.acct).slice(-4)}`,3],['W-9',d.w9?'Signed':'<b class="errc">Not completed</b>',3],['Store',`${d.store} · ${d.cats.map(cn).join(', ')} · ${d.skus} products`,4]].map(([k,v,s])=>`<div class="kv sm" style="padding:8px 0;border-bottom:1px solid var(--line-2)"><span>${k}</span><span class="right">${v} <a class="lnk xs" onclick="S.seller.onboard.step=${s};render('seller',true)">Edit</a></span></div>`).join('')}
    <label class="row g8 sm start mt12"><input type="checkbox" checked style="margin-top:3px"> I agree to the EcomDemo Business Solutions Agreement and confirm the information is accurate.</label></div>`];
  return{title:'Register a new business',sub:'Know Your Business (KYB) verification',body:`${st>0?`<div class="steps">${OB_STEPS.map((s,i)=>`<div class="${i+1<st?'done':i+1===st?'cur':''}"><i>${i+1<st?ic('check','sm'):i+1}</i>${s}</div>`).join('')}</div>`:''}${bodies[st]}${nav}`}};
function submitOnboard(){const d=obD();if(!d.idDoc||!d.w9){toast(!d.idDoc?'Upload the owner ID first':'Complete the W-9 tax interview','alert');S.seller.onboard.step=!d.idDoc?2:3;render('seller',true);return}
  const id='APP-'+(3310+S.apps.length);S.apps.unshift({id,legal:d.legal,store:d.store,entity:d.entity,state:d.state==='California'?'CA':d.state,ein:'**-***'+d.ein.slice(-4),rep:d.owner,cat:d.cats[0]||'pantry',city:d.addr.split(',').slice(-2).join(',').trim(),checks:{ein:'pass',id:'pass',bank:'pass',ofac:'pass',address:'review'},risk:'Low',status:'pending',submitted:Date.now(),skus:d.skus,mine:true});
  S.seller.onboard.status='submitted';S.seller.onboard.appId=id;notify('admin',`New seller application <b>${esc(d.legal)}</b>`,['sellers',{}]);toast('Application submitted for verification','id');render('seller',true);if(onStage('admin'))render('admin')}
